window.FILM_WORK_PROMPTS={"work_id":"src-006adfcdecd7fc72","records":[{"work_id":"src-006adfcdecd7fc72","frame_id":"FG-be442943f6425e7f","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Starfish_007.jpg","source_page":"https://film-grab.com/2020/08/08/starfish/","scene":"黄昏或黎明时分的天空背景，一根深色电线杆矗立画面右侧，杆上装有圆柱形变压器和向左伸出的路灯，多条电线纵横交错，右侧天空中悬挂着一轮明月。","analysis":"画面采用仰视视角拍摄，电线杆位于右侧三分之一处，路灯向左延伸形成视觉平衡。天空呈现均匀的灰蓝色调，光线柔和暗淡，电线与杆体形成黑色剪影。右侧的月亮作为唯一亮点，与暗色前景形成对比。整体色调偏冷，带有颗粒感，营造出静谧、略带忧郁的氛围。","prompt":"仰视视角的黄昏天空，灰蓝色背景中悬挂着一轮清晰的白色月亮。画面右侧矗立着一根深色木质电线杆，杆身粗糙，上方固定着一个圆柱形的变压器设备。一根弯曲的金属灯杆从电线杆中部向左延伸，末端连接着扁平的路灯灯头。多条黑色电线在天空中纵横交错，形成复杂的几何线条。整体光线昏暗，前景物体呈现剪影效果，天空色彩均匀，画面带有明显的胶片颗粒质感，氛围静谧冷清。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T04:58:30-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Starfish_007.jpg","observed_dimensions":[1280,545],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.507,"observed_resolution":"normal","observation_limits":[],"id":"VP-75171cf8179ae17f","origin":"visual"},{"work_id":"src-006adfcdecd7fc72","frame_id":"FG-cf3bea92b755c407","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Starfish_020.jpg","source_page":"https://film-grab.com/2020/08/08/starfish/","scene":"金发人物身穿芥末黄上衣，侧身蜷缩在条纹织物座椅中，头部低垂，背景为模糊的灰白色斑驳纹理。","analysis":"画面采用俯视角度，人物位于画面左侧，仅上半身及头部可见，身体蜷缩，头部靠在座椅靠背上。人物面部朝向右下方，双眼闭合。光线柔和，人物面部与黄色衣物受光，背景处于暗部且失焦，形成明暗对比。","prompt":"俯视视角，一名金发人物身穿芥末黄色长袖上衣，侧身蜷缩在带有细密条纹的灰褐色织物座椅中。人物头部低垂，面部朝向右下方，双眼闭合，神情平静。座椅靠背占据画面左上角，纹理清晰。背景为大面积失焦的灰白色斑驳纹理，光线柔和，人物面部与黄色衣物受光，与暗部背景形成对比。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T04:58:36-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Starfish_020.jpg","observed_dimensions":[1280,545],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.506,"observed_resolution":"normal","observation_limits":[],"id":"VP-85b7e65314486f2e","origin":"visual"},{"work_id":"src-006adfcdecd7fc72","frame_id":"FG-098bafc2f83fa2dc","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Starfish_033.jpg","source_page":"https://film-grab.com/2020/08/08/starfish/","scene":"昏暗室内，一名金发女子斜靠在灰色条纹沙发上，周围散布着多盏点亮的油灯和蜡烛，前景有模糊的瓶罐与烛台，背景是摆满杂物的架子。","analysis":"画面采用前景虚化构图，焦点位于中景人物。女子上半身可见，呈放松坐姿，头部微侧。环境占据大部分画面，营造出封闭感。光线主要来自多处暖色点光源，形成强烈的明暗对比，人物面部受光柔和，背景深邃，整体色调偏暖黄与暗褐。","prompt":"昏暗的室内场景，一名金发女子身穿灰色T恤，慵懒地斜靠在宽大的灰色条纹布艺沙发上，左手抬起触碰头部。前景极度虚化，可见模糊的深色瓶罐轮廓和明亮的烛火。中景清晰，女子周围散落着书籍和杂物。环境光线昏暗，主要依靠多盏点亮的复古油灯和蜡烛照明，散发出温暖的橙黄色光芒，照亮了女子的面部和上半身，背景深处是模糊的书架和挂饰，整体氛围静谧且充满生活气息。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T04:58:43-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Starfish_033.jpg","observed_dimensions":[1280,545],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.499,"observed_resolution":"normal","observation_limits":[],"id":"VP-f8d518a1b468264d","origin":"visual"},{"work_id":"src-006adfcdecd7fc72","frame_id":"FG-55df85785ec5b7d2","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Starfish_046.jpg","source_page":"https://film-grab.com/2020/08/08/starfish/","scene":"画面主体为一名金发女性的面部特写，头部横向倾斜，背景上方可见红色衣物与白色亮片装饰，前景下方有大面积模糊遮挡。","analysis":"构图极度紧凑，人物面部占据画面中心，呈横向倒置姿态。仅可见头部及颈部上方，前景下方有模糊的深色物体遮挡视线。光线昏暗，整体笼罩在深红色调中，背景上方的白色亮片形成高光点，与暗部形成对比，营造出一种压抑且神秘的视觉氛围。","prompt":"一张极度特写的电影感静帧，画面主体为一名金发女性的面部，头部横向倒置。她的眼神平静地注视着镜头，面部皮肤在暗光下呈现红润色泽。背景上方可见红色衣物及一排白色圆形亮片装饰，在暗处闪烁。前景下方有大面积失焦的深色模糊色块，遮挡了画面底部，增加了窥视感。整体色调为深红与暗褐，光影对比强烈，营造出一种私密、压抑且充满张力的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T04:58:50-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Starfish_046.jpg","observed_dimensions":[1280,545],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.488,"observed_resolution":"normal","observation_limits":[],"id":"VP-6f0b08c976f01112","origin":"visual"},{"work_id":"src-006adfcdecd7fc72","frame_id":"FG-3702b05bd72531ac","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Starfish_059.jpg","source_page":"https://film-grab.com/2020/08/08/starfish/","scene":"一名留着短胡须的男子身穿黑色短袖T恤，背靠粉紫色砖墙坐着，身体略微侧向，目光望向画面左侧，右侧前景有大面积模糊的深蓝色遮挡物。","analysis":"画面主体为男子上半身，头部至大腿部分可见，右侧约三分之一画面被模糊的深蓝色块占据，形成前景遮挡。人物位于画面左侧，背景为粉紫色砖墙，砖缝清晰可见。光线柔和，整体色调偏冷，带有明显的颗粒感，人物面部受光均匀，阴影柔和，营造出一种静谧、略带忧郁的视觉氛围。","prompt":"一名留着短胡须的年轻男子，身穿黑色圆领短袖T恤，背靠粉紫色砖墙坐着。他身体略微侧向，目光望向画面左侧，神情平静。画面右侧前景有大面积模糊的深蓝色遮挡物，占据约三分之一画面，形成前景虚化效果。背景为粉紫色砖墙，砖缝清晰可见。光线柔和，整体色调偏冷，带有明显的颗粒感，人物面部受光均匀，阴影柔和，营造出一种静谧、略带忧郁的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T04:58:57-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Starfish_059.jpg","observed_dimensions":[1280,545],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.526,"observed_resolution":"normal","observation_limits":[],"id":"VP-f1d7110a0c0d06f8","origin":"visual"},{"work_id":"src-006adfcdecd7fc72","frame_id":"FG-f5138a6088b1cda9","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Starfish_008.jpg","source_page":"https://film-grab.com/2020/08/08/starfish/","scene":"金发女性面部与双手占据画面主体，双手张开按在玻璃上，背景为模糊的冷色调环境，整体氛围阴郁压抑。","analysis":"人物面部位于画面中央，双手分列左右两侧，手掌贴附在透明介质上，手指轮廓清晰。人物上半身可见，头部与双手在画面中占比极大。光线昏暗，整体呈现冷蓝色调，面部受光微弱，背景虚化严重，仅能辨识模糊的色块与轮廓，明暗对比集中在面部与手部边缘。","prompt":"画面主体为一名金发女性的面部特写，她神情凝重，目光直视前方。她的双手张开，手掌平贴在面前的透明玻璃或窗面上，手指修长，指尖触碰到介质表面。人物占据画面绝大部分空间，背景处于极度虚化状态，呈现出模糊的冷蓝色与暗灰色块，无法辨识具体环境细节。整体光线昏暗，色调偏冷，面部光影柔和但缺乏高光，营造出一种阴冷、压抑且充满张力的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T19:11:35+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Starfish_008.jpg","observed_dimensions":[1280,545],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.474,"observed_resolution":"normal","observation_limits":[],"id":"VP-0e66fba058df406c","origin":"visual"},{"work_id":"src-006adfcdecd7fc72","frame_id":"FG-6070afbb87a39b89","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Starfish_021.jpg","source_page":"https://film-grab.com/2020/08/08/starfish/","scene":"蓝色磁带特写，上方白色标签手写“#7”，中间黄色窗口显示磁带卷绕状态，两侧黑色卷轴清晰可见。","analysis":"画面主体为磁带局部，占据全幅。上方白色标签带手写黑色字符，下方蓝色塑料壳体。中间矩形窗口透出黄色磁带，左侧卷轴较暗，右侧较亮。刻度“100 50 0”印于窗口下方。光线从上方投射，形成明暗对比，整体色调偏冷蓝与暖黄交织。","prompt":"蓝色塑料磁带外壳特写，上方白色标签纸手写黑色“#7”字样，左侧印有字母“B”。中间矩形窗口内可见黄色磁带卷绕，左侧卷轴呈深色圆形，右侧卷轴略亮。窗口下方印有白色刻度“100 50 0”。整体光线柔和，上方略亮，下方渐暗，色调以冷蓝为主，窗口区域透出暖黄色光，质感细腻，细节清晰。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T19:11:44+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Starfish_021.jpg","observed_dimensions":[1280,545],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.499,"observed_resolution":"normal","observation_limits":[],"id":"VP-d82b28d473e1c064","origin":"visual"},{"work_id":"src-006adfcdecd7fc72","frame_id":"FG-f6741994915fc8ae","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Starfish_034.jpg","source_page":"https://film-grab.com/2020/08/08/starfish/","scene":"昏暗的木质走廊内，一名金发年轻女子站立在画面中央，右手高举着一盏发光的提灯，照亮了周围深色的木板墙壁和门框。","analysis":"画面采用中心构图，人物位于视觉焦点。人物上半身及大腿部分清晰可见，头部至膝盖以下被阴影或画框截断。拍摄视角接近平视，光线主要来自人物手中的提灯，形成强烈的明暗对比。暖黄色的灯光照亮了人物的面部、金发和浅色T恤，而周围环境则沉浸在深沉的暗红色和黑色阴影中，营造出一种幽闭、神秘且略带不安的视觉氛围。","prompt":"昏暗的木质结构室内，一名金发年轻女子站在画面中央，身穿浅色印花T恤，肩挎深色包带。她右手高举一盏发光的复古提灯，暖黄色的灯光从下向上照亮她的面部和上半身，形成强烈的明暗对比。背景是深色的木板墙壁和门框，右侧挂着一块浅色织物，左侧墙壁上有模糊的矩形物体。整体色调偏暗，以深褐色和黑色为主，仅提灯周围有暖色光晕，营造出幽闭、神秘且略带不安的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T19:11:57+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Starfish_034.jpg","observed_dimensions":[1280,545],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.444,"observed_resolution":"normal","observation_limits":[],"id":"VP-e93302758e93705d","origin":"visual"},{"work_id":"src-006adfcdecd7fc72","frame_id":"FG-5bdd89d9390291c1","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Starfish_047.jpg","source_page":"https://film-grab.com/2020/08/08/starfish/","scene":"一名金发人物盘腿坐在昏暗房间中央，身穿深色格纹衬衫与灰色外套，低头注视手中物体。四周堆满书籍，左侧台灯发出冷白光，右侧书架隐约可见。","analysis":"人物位于画面中心，上半身及大腿可见，呈盘腿坐姿，双手置于膝前。环境占比极大，左右两侧及身后均为高耸的书堆与书架，形成包围感。左侧台灯提供主要冷色光源，照亮人物面部与上半身，右侧及背景陷入深暗阴影，明暗对比强烈，色调偏冷蓝。","prompt":"昏暗室内，一名金发人物盘腿坐于地面中央，身穿深色格纹衬衫外搭灰色长袖外套，低头注视手中物体。人物周围被大量书籍包围，左侧书堆上方有一盏发出冷白光的台灯，右侧为深色木质书架，架上排列着彩色书脊。背景深处堆叠着更多书籍，整体环境幽暗，仅左侧光源照亮人物面部与上半身，形成强烈的明暗对比，色调偏冷蓝，营造出静谧封闭的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T19:12:04+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Starfish_047.jpg","observed_dimensions":[1280,545],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.424,"observed_resolution":"normal","observation_limits":[],"id":"VP-06dbc651fcc718fc","origin":"visual"},{"work_id":"src-006adfcdecd7fc72","frame_id":"FG-786d19e4aaaa05a2","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Starfish_060.jpg","source_page":"https://film-grab.com/2020/08/08/starfish/","scene":"画面主体为一只动物头部的局部特写，可见闭合的眼睑、鼻部轮廓及嘴部结构，背景为模糊的灰白色调，无其他清晰环境元素。","analysis":"构图极度紧凑，主体占据画面绝大部分空间，仅展示面部局部。视角略微俯视，光线柔和且对比度低，整体呈现灰阶色调。明暗层次细腻，从深灰色的阴影过渡到浅灰色的高光，质感柔和，无强烈光源方向。","prompt":"这是一张极度特写的黑白摄影作品，画面主体是一只动物头部的局部，占据了几乎整个画幅。可以看到闭合的眼睑、鼻部的轮廓以及嘴部结构，毛发质感细腻柔和。背景处于失焦状态，呈现模糊的灰白色调，与主体形成虚实对比。光线非常柔和，没有强烈的明暗交界线，整体影调偏向中灰，营造出一种静谧、安详且略带忧郁的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T19:12:14+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Starfish_060.jpg","observed_dimensions":[1280,545],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.504,"observed_resolution":"normal","observation_limits":[],"id":"VP-6a50d6870139b24e","origin":"visual"}]};